namespace regrip_three_resume {
class StationarySupportTransferODE:public StationaryPersistentODE {
public:
 SOFA_CLASS(StationarySupportTransferODE,StationaryPersistentODE);
 void solve(const sofa::core::ExecParams*,SReal dt,sofa::core::MultiVecCoordId,sofa::core::MultiVecDerivId)override{
  if(!restored||count!=0||dt!=savedDt||dt!=.0002||getContext()->getTime()!=initialTime||!(initialTime>.0225&&initialTime<.0227)||externalForce.getValue()!=sofa::type::Vec3(0,0,0))throw std::runtime_error("isolated actual stationary edge115/face117200us fixture required");
  last=getContext()->getTime();SharedFilmSystem s(Layout(),{0,0,0},true,true);s.exactUnresolved=true;Eigen::VectorXd q=s.initial,v=Eigen::VectorXd::Zero(q.size());readActual(s,q,v);auto r=stationaryEdgeFaceTransfer(s,q,v,last,dt);
  if(r.active.size()!=3)throw std::runtime_error("new active set cannot fit qualified three-row checkpoint;NO commit");for(unsigned f=0;f<3;++f){const auto&o=r.active[f];auto row=s.selected(r.post.q,f);if(o.finger!=f||o.triangle!=117||o.feature!=6||row.triangle!=o.triangle||row.feature!=o.feature)throw std::runtime_error("new actual selected/owned support mismatch");}
  auto open=[&](const char*suffix){std::string path=filename.getValue()+suffix;if(std::ifstream(path))throw std::runtime_error("support transfer journal exists");std::ofstream out(path);out<<std::setprecision(17);return out;};
  auto event=open(".support.event.csv");double difference=0;for(unsigned f=0;f<3;++f)difference=std::max(difference,(r.eventGeometry.J.row(f)-r.eventGeometry.J.row(f+3)).norm());event<<"event_time,bracket_s,all_rows,active_rows,rank,J_difference_norm,new_min_vminus_mm_s,impact_loss_Nmm,momentum_Ns,qminus,vminus,vplus,impulse_Ns\n"<<last+r.fractionTime<<','<<r.bracketWidth<<','<<r.all.size()<<','<<r.active.size()<<','<<r.impact.rank<<','<<difference<<','<<(r.eventGeometry.J.bottomRows(3)*r.pre.v).minCoeff()<<','<<r.impact.state.energyLoss<<','<<r.impact.state.momentumResidual;quote(event,r.pre.q);quote(event,r.pre.v);quote(event,r.impact.state.velocity);quote(event,r.impact.state.impulse);event<<'\n';event.flush();
  double vn=1e99;unsigned touching=0;for(unsigned f=0;f<3;++f){auto local=s.local(r.pre.q,f);for(unsigned k=0;k<s.shared.films[f].triangles.size();++k){auto row=s.shared.films[f].geometry(local,k);if(std::abs(row.gap)>1e-12)continue;Eigen::RowVectorXd J=Eigen::RowVectorXd::Zero(q.size());J.segment(f*s.shared.nf,s.shared.nf)=row.gradient.head(s.shared.nf).transpose();J.segment<3>(3*s.shared.nf)=row.gradient.segment<3>(s.shared.nf).transpose()*s.layout.mount[f].R.transpose();vn=std::min(vn,J.dot(r.impact.state.velocity));++touching;}}if(vn< -1e-10)throw std::runtime_error("other touching surface enters after impact;NO commit");
  auto metrics=open(".support.metrics.csv");metrics<<"time,gap_mm,linear_balance_Ns,angular_balance_Nmms,root_impulse_Ns,root_moment_Nmms,touching_rows,touching_min_vplus_mm_s,q,v\n"<<last+dt<<','<<r.minimumGap<<','<<r.linearBalance<<','<<r.angularBalance<<','<<r.rootImpulse.norm()<<','<<r.rootMoment.norm()<<','<<touching<<','<<vn;quote(metrics,r.post.q);quote(metrics,r.post.v);metrics<<'\n';metrics.flush();
  auto stages=open(".support.stages.csv");stages<<"segment,stage,time,weight_s,finger,triangle,feature,gap,force,normal_velocity,tension,q,v\n";
  auto journal=[&](unsigned segment,const auto&result,const Eigen::VectorXd&x0,const Eigen::VectorXd&v0,double start,double h,const auto&owners){for(unsigned k=0;k<3;++k){const auto&x=k?result.stages[k-1].q:x0;const auto&vel=k?result.stages[k-1].v:v0;auto g=ownedGeometry(s,x,owners);double t=start+h*(k==0?0:k==1?.5:1),weight=h*(k==1?2./3:1./6);for(unsigned i=0;i<owners.size();++i){const auto&o=owners[i];double force=k?result.stages[k-1].force(i):result.initialForce(i);stages<<segment<<','<<k<<','<<t<<','<<weight<<','<<o.finger<<','<<o.triangle<<','<<o.feature<<','<<g.gap(i)<<','<<force<<','<<g.J.row(i).dot(vel)<<','<<regrip_film_rail::ControlProfile::evaluate(t,.0001,.01,.02,.03,true).tension;quote(stages,x);quote(stages,vel);stages<<'\n';auto row=s.shared.films[o.finger].geometry(s.local(x,o.finger),o.triangle);Eigen::Vector3d normal=s.layout.mount[o.finger].R*row.normal,point=s.layout.mount[o.finger].origin+s.layout.mount[o.finger].R*row.contact;rowJournal<<t<<','<<o.finger<<','<<o.triangle<<','<<o.feature<<','<<g.gap(i)<<','<<force<<','<<g.J.row(i).dot(vel);for(double z:normal)rowJournal<<','<<z;for(double z:point)rowJournal<<','<<z;quote(rowJournal,g.J.row(i));quote(rowJournal,x);quote(rowJournal,vel);rowJournal<<'\n';}}};journal(0,r.pre,q,v,last,r.fractionTime,r.old);journal(1,r.post,r.pre.q,r.impact.state.velocity,last+r.fractionTime,dt-r.fractionTime,r.active);stages.flush();rowJournal.flush();
  auto impulses=open(".support.impulses.csv");impulses<<"event_time,row,finger,triangle,feature,impulse_Ns,vminus_mm_s,vplus_mm_s,jacobian\n";for(unsigned i=0;i<r.all.size();++i){const auto&o=r.all[i];impulses<<last+r.fractionTime<<','<<i<<','<<o.finger<<','<<o.triangle<<','<<o.feature<<','<<r.impact.state.impulse(i)<<','<<r.eventGeometry.J.row(i).dot(r.pre.v)<<','<<r.impact.state.normalVelocity(i);quote(impulses,r.eventGeometry.J.row(i));impulses<<'\n';}impulses.flush();
  lastImpactTime=last+r.fractionTime;commitActual(s,r.post.q,r.post.v,last+dt);accepted<<last+dt<<','<<r.minimumGap<<','<<std::max(r.pre.momentumResidual,r.post.momentumResidual)<<','<<std::max(r.pre.velocityResidual,r.post.velocityResidual)<<','<<r.pre.iterations+r.post.iterations<<','<<r.pre.evaluations+r.post.evaluations;quote(accepted,r.post.q);quote(accepted,r.post.v);accepted<<'\n';accepted.flush();++count;save(last+dt);
 }
};
}
